```

If `dataRead < size`, the remaining bytes are zeroed. So no uninitialized values here.

But what if `dataRead` is exactly `size`? Then all bytes are initialized from the file. No issue.

So the non-RLE path is safe. The issue must be in the RLE path.

Let me look at the RLE path again:

```c
if (info.rle) {
    // Decode image.
    char *dst = (char *)image;
    qint64 num = size;

    while (num > 0) {
        if (s.atEnd()) {
            valid = false;
            break;
        }

        // Get packet header.
        uchar c;
        s >> c;

        uint count = (c & 0x7f) + 1;
        num -= count * pixel_size;
        if (num < 0) {
            valid = false;
            break;
        }

        if (c & 0x80) {
            // RLE pixels.
            assert(pixel_size <= 8);
            char pixel[8];
            s.readRawData(pixel, pixel_size);
            do {
                memcpy(dst, pixel, pixel_size);
                dst += pixel_size;
            } while (--count);
        } else {
            // Raw pixels.
            count *= pixel_size;
            s.readRawData(dst, count);
            dst += count;
        }
    }
}
```

